package com.college.attendance.mobile.ui;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.*;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import com.college.attendance.mobile.R;
import com.college.attendance.mobile.api.ApiClient;
import com.college.attendance.mobile.model.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import retrofit2.*;

public class DashboardActivity extends AppCompatActivity {
 private LinearLayout actions; private TextView title,welcome,out; private ProgressBar progress; private String role;
 @Override public void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.activity_dashboard);title=findViewById(R.id.title);welcome=findViewById(R.id.welcome);out=findViewById(R.id.output);actions=findViewById(R.id.actions);progress=findViewById(R.id.progress);role=getSharedPreferences("auth",0).getString("role","STUDENT");String name=getSharedPreferences("auth",0).getString("name","");title.setText(role+" MODULE");welcome.setText("Welcome, "+name+"\nAccess is based on your role.");build();}
 private void btn(String text,View.OnClickListener listener){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextSize(16);b.setMinHeight(dp(52));b.setOnClickListener(listener);actions.addView(b);}
 private void build(){if(role.equals("STUDENT")){btn("1. Mark Attendance (Face)",v->loadActive());btn("Register / Update Face",v->registerFace());btn("2. View Attendance",v->studentAttendance());btn("3. Assignments",v->assignments());btn("4. Feedback / Complaints",v->complaintDialog());}else if(role.equals("TEACHER")){btn("1. Create Attendance Session",v->createSession());btn("2. View Sessions",v->teacherSessions());btn("3. View Student Attendance",v->teacherSessionsForAttendance());btn("4. Assignments",v->assignments());btn("5. Doubts / Complaints",v->teacherComplaints());}else{btn("1. Search & View Students",v->hodStudents());btn("2. Monitoring / Analytics",v->analytics());btn("3. Complaints & Feedback",v->toast("HOD complaints screen is not connected yet."));btn("4. User Management",v->toast("User management screen is not connected yet."));}}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private void loading(String text){progress.setVisibility(View.VISIBLE);out.setVisibility(View.VISIBLE);out.setText(text);actions.setEnabled(false);}
 private void done(){progress.setVisibility(View.GONE);}
 private void empty(String text){out.setVisibility(View.VISIBLE);out.setText(text);}
 private void error(String text){done();out.setVisibility(View.VISIBLE);out.setText(text);}
 private String callError(Response<?> r){return r.code()==401?"Your session expired. Please log in again.":r.code()==403?"You do not have permission to view this information.":"Could not load data (HTTP "+r.code()+").";}
 private void card(String heading,String detail){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(14),dp(16),dp(14));c.setBackgroundColor(0xFFFFFFFF);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));actions.addView(c,lp);TextView h=new TextView(this);h.setText(heading);h.setTextSize(17);h.setTextColor(0xFF07579B);h.setTypeface(null,1);c.addView(h);TextView d=new TextView(this);d.setText(detail);d.setTextSize(14);d.setPadding(0,dp(6),0,0);c.addView(d);}
 private void loadActive(){ApiClient.get(this).activeSession().enqueue(new Callback<Session>(){public void onResponse(Call<Session> c,Response<Session> r){if(r.isSuccessful()&&r.body()!=null){Map<String,Object> b=new HashMap<>();b.put("sessionId",r.body().id);ApiClient.get(DashboardActivity.this).startVerification(b).enqueue(new Callback<VerificationAttempt>(){public void onResponse(Call<VerificationAttempt> c,Response<VerificationAttempt> a){if(a.isSuccessful()&&a.body()!=null){Intent i=new Intent(DashboardActivity.this,FaceCaptureActivity.class);i.putExtra("attemptId",a.body().attemptId);startActivity(i);}else toast("Unable to start verification.");}public void onFailure(Call<VerificationAttempt> c,Throwable t){toast(t.getMessage());}});}else toast("No active session for your section.");}public void onFailure(Call<Session> c,Throwable t){toast(t.getMessage());}});}
 private void registerFace(){Intent i=new Intent(this,FaceCaptureActivity.class);i.putExtra("register",true);startActivity(i);}
 private void studentAttendance(){loading("Loading attendance…");ApiClient.get(this).studentAttendance().enqueue(new Callback<List<AttendanceRecord>>(){public void onResponse(Call<List<AttendanceRecord>> c,Response<List<AttendanceRecord>> r){done();if(!r.isSuccessful()){error(callError(r));return;}actions.removeAllViews();List<AttendanceRecord> rows=r.body();if(rows==null||rows.isEmpty()){empty("No attendance records yet.");return;}for(AttendanceRecord a:rows)card(a.session!=null&&a.session.subject!=null?a.session.subject.name:"Attendance",safe(a.status)+"  •  "+format(a.markedAt));}public void onFailure(Call<List<AttendanceRecord>> c,Throwable t){error("Network error: "+t.getMessage());}});}
 private void createSession(){loading("Loading assigned subjects…");ApiClient.get(this).subjects().enqueue(new Callback<List<Subject>>(){public void onResponse(Call<List<Subject>> c,Response<List<Subject>> r){done();if(!r.isSuccessful()){error(callError(r));return;}if(r.body()==null||r.body().isEmpty()){empty("No subjects are assigned to your account.");return;}String[] labels=new String[r.body().size()];for(int i=0;i<labels.length;i++)labels[i]=r.body().get(i).code+" — "+r.body().get(i).name+" ("+r.body().get(i).section+")";new AlertDialog.Builder(DashboardActivity.this).setTitle("Select subject").setItems(labels,(d,which)->startSession(r.body().get(which))).setNegativeButton("Cancel",null).show();}public void onFailure(Call<List<Subject>> c,Throwable t){error("Network error: "+t.getMessage());}});}
 private void startSession(Subject s){Map<String,Object>b=new HashMap<>();b.put("subjectId",s.id);b.put("section",s.section);b.put("durationMinutes",15);loading("Creating attendance session…");ApiClient.get(this).createSession(b).enqueue(new Callback<Session>(){public void onResponse(Call<Session> c,Response<Session> r){done();if(r.isSuccessful()&&r.body()!=null){empty("Attendance session started for "+s.code+" • "+s.section);teacherSessions();}else error(callError(r));}public void onFailure(Call<Session> c,Throwable t){error("Network error: "+t.getMessage());}});}
 private void teacherSessions(){showSessions(false);}
 private void teacherSessionsForAttendance(){showSessions(true);}
 private void showSessions(boolean attendanceMode){loading("Loading sessions…");ApiClient.get(this).teacherSessions().enqueue(new Callback<List<Session>>(){public void onResponse(Call<List<Session>> c,Response<List<Session>> r){done();if(!r.isSuccessful()){error(callError(r));return;}List<Session> rows=r.body();actions.removeAllViews();if(rows==null||rows.isEmpty()){empty("No attendance sessions yet.");return;}for(Session s:rows){String subject=s.subject==null?"Subject":safe(s.subject.code)+" — "+safe(s.subject.name);card(subject,"Section "+safe(s.section)+"\n"+format(s.startTime)+" to "+format(s.endTime)+"\n"+(s.active?"ACTIVE":"CLOSED"));Button view=new Button(DashboardActivity.this);view.setText("View Attendance");view.setAllCaps(false);actions.addView(view);view.setOnClickListener(v->sessionAttendance(s));if(s.active){Button close=new Button(DashboardActivity.this);close.setText("Close Session");close.setAllCaps(false);actions.addView(close);close.setOnClickListener(v->closeSession(s));}}}public void onFailure(Call<List<Session>> c,Throwable t){error("Network error: "+t.getMessage());}});}
 private void closeSession(Session s){new AlertDialog.Builder(this).setTitle("Close session?").setMessage("Students will no longer be able to mark attendance in this session.").setNegativeButton("Cancel",null).setPositiveButton("Close",(d,w)->ApiClient.get(this).closeSession(s.id).enqueue(new Callback<Session>(){public void onResponse(Call<Session> c,Response<Session> r){if(r.isSuccessful())teacherSessions();else toast(callError(r));}public void onFailure(Call<Session> c,Throwable t){toast(t.getMessage());}})).show();}
 private void sessionAttendance(Session s){loading("Loading session attendance…");ApiClient.get(this).sessionAttendance(s.id).enqueue(new Callback<List<AttendanceRecord>>(){public void onResponse(Call<List<AttendanceRecord>> c,Response<List<AttendanceRecord>> r){done();if(!r.isSuccessful()){error(callError(r));return;}actions.removeAllViews();List<AttendanceRecord> rows=r.body();if(rows==null||rows.isEmpty()){empty("No attendance has been recorded for this session.");return;}int present=0;for(AttendanceRecord a:rows)if("PRESENT".equalsIgnoreCase(a.status))present++;card("Attendance summary",rows.size()+" present records");for(AttendanceRecord a:rows){Student st=a.student;String name = "Student";String roll=st==null?"":safe(st.rollNumber);card(name,(roll.isEmpty()?"":roll+" • ")+safe(a.status)+" • "+format(a.markedAt));}}public void onFailure(Call<List<AttendanceRecord>> c,Throwable t){error("Network error: "+t.getMessage());}});}
 private void assignments(){loading("Loading assignments…");ApiClient.get(this).assignments().enqueue(new Callback<List<Assignment>>(){public void onResponse(Call<List<Assignment>> c,Response<List<Assignment>> r){done();if(!r.isSuccessful()){error(callError(r));return;}actions.removeAllViews();if(r.body()==null||r.body().isEmpty()){empty("No assignments found.");return;}for(Assignment a:r.body()){String subject=a.subject==null?"Subject":safe(a.subject.code)+" — "+safe(a.subject.name);String section=a.subject==null?"":a.subject.section;card(safe(a.title),subject+(section==null?"":" • "+section)+"\nDue "+safe(a.dueDate)+(a.description==null||a.description.isEmpty()?"":"\n"+a.description));}}public void onFailure(Call<List<Assignment>> c,Throwable t){error("Network error: "+t.getMessage());}});}
 private void teacherComplaints(){empty("Teacher complaint review is not available: the backend has no endpoint to list student complaints. Only HOD complaint administration is supported.");}
 private void hodStudents(){loading("Loading students…");ApiClient.get(this).hodStudents().enqueue(new Callback<List<Student>>(){public void onResponse(Call<List<Student>> c,Response<List<Student>> r){done();if(!r.isSuccessful()){error(callError(r));return;}out.setText(new com.google.gson.Gson().toJson(r.body()));}public void onFailure(Call<List<Student>> c,Throwable t){error(t.getMessage());}});}
 private void analytics(){loading("Loading analytics…");ApiClient.get(this).analytics().enqueue(new Callback<Map<String,Object>>(){public void onResponse(Call<Map<String,Object>> c,Response<Map<String,Object>> r){done();if(r.isSuccessful()&&r.body()!=null){actions.removeAllViews();for(Map.Entry<String,Object> e:r.body().entrySet())card(e.getKey(),String.valueOf(e.getValue()));}else error(callError(r));}public void onFailure(Call<Map<String,Object>> c,Throwable t){error(t.getMessage());}});}
 private void complaintDialog(){EditText e=new EditText(this);e.setHint("Complaint / feedback");new AlertDialog.Builder(this).setTitle("Feedback / Complaint").setView(e).setPositiveButton("Submit",(d,w)->toast("Complaint submission is not connected yet.")).setNegativeButton("Cancel",null).show();}
 private void toast(String s){Toast.makeText(this,s==null?"Error":s,Toast.LENGTH_LONG).show();}
 private String safe(String s){return s==null||s.isBlank()?"—":s;}
 private String format(String value){if(value==null)return "—";try{return LocalDateTime.parse(value).format(DateTimeFormatter.ofPattern("dd MMM yyyy, hh:mm a"));}catch(Exception ignored){return value;}}
}
